    private static final class RecordingResolver extends android.content.ContentResolver{final List<String> changes=new ArrayList<>();@java.lang.Override public void notifyChange(Uri uri,android.database.ContentObserver observer){super.notifyChange(uri,observer);changes.add(uri.toString());}}
    private static final class FilesContext extends Context{final Path path;final RecordingResolver resolver=new RecordingResolver();boolean failMarkerWrites;final Map<String,ActivationGuardPreferencesCheck.MemoryPreferences> preferences=new HashMap<>();final Map<String,SharedPreferences> broken=new HashMap<>();FilesContext(Path path){this.path=path;}@java.lang.Override public File getFilesDir(){return path.toFile();}@java.lang.Override public android.content.ContentResolver getContentResolver(){return resolver;}@java.lang.Override public SharedPreferences getSharedPreferences(String name,int mode){SharedPreferences normal=preferences.computeIfAbsent(name,k->new ActivationGuardPreferencesCheck.MemoryPreferences());return failMarkerWrites?broken.computeIfAbsent(name,k->failingCommits(normal)):normal;}}
    private static void previewPixels(Bitmap image,int budget,String why){
        try{equal(true,image!=null&&!image.isRecycled()&&image.getWidth()>0&&image.getHeight()>0&&image.getWidth()<=budget&&image.getHeight()<=budget,why+" returns a bounded real image");
            int[] pixels=new int[image.getWidth()*image.getHeight()];image.getPixels(pixels,0,image.getWidth(),0,0,image.getWidth(),image.getHeight());int maxAlpha=0;for(int pixel:pixels)maxAlpha=Math.max(maxAlpha,pixel>>>24);equal(128,maxAlpha,why+" contains the actual semi-transparent PNG artwork");
        }finally{if(image!=null)image.recycle();}
    }
