    private static void checkPositive(int number,String why){equal(true,number>0,why);}
    private static void portable()throws Exception{
        for(String old:IconManagementSettings.LEGACY_KEYS)equal(false,ConfigTransfer.types().containsKey(old),"retired icon field not exported");equal(ConfigTransfer.Type.STRING,ConfigTransfer.types().get(IconManagementSettings.KEY),"new record exported");
        String records=IconManagementSettings.applyPack(IconManagementSettings.DEFAULT,A,Arrays.asList("hint"),false);Map<String,Object> selected=map("status_icon_pack_enabled",true,"status_icon_pack_layers","broken old list","status_icon_pack_assignments",map("arbitrary","ignored"),"clock_pattern","HH:mm:ss",IconManagementSettings.KEY,records);
        ConfigTransfer.PreparedImport prepared=ConfigTransfer.prepare(json(map("package",ConfigTransfer.PACKAGE_NAME,"schema",1,"settings",selected)),true);equal(3,prepared.skippedLegacyIcons,"old full backup explicitly reports skipped fields");equal(2,prepared.count,"other legal fields continue importing");
        ActivationGuardPreferencesCheck.MemoryPreferences raw=new ActivationGuardPreferencesCheck.MemoryPreferences();raw.values.put("status_icon_pack_enabled",false);raw.values.put("private_note","keep");equal(true,ConfigTransfer.commit(raw,prepared),"mixed backup commits legal subset");equal(false,raw.values.get("status_icon_pack_enabled"),"old backup cannot revive legacy renderer");equal("keep",raw.values.get("private_note"),"private sibling remains");equal("HH:mm:ss",raw.values.get("clock_pattern"),"ordinary module value imported");
        ConfigTransfer.PreparedImport oldOnly=ConfigTransfer.prepare(json(map("package",ConfigTransfer.PACKAGE_NAME,"schema",1,"settings",map("status_icon_pack_enabled",true))),true);equal(0,oldOnly.count,"legacy-only backup has no applied settings");int writes=raw.writes;equal(false,ConfigTransfer.commit(raw,oldOnly),"legacy-only backup makes no incidental edits");equal(writes,raw.writes,"legacy-only backup leaves storage untouched");
    }
    private static void downloads()throws Exception{equal("owner/repo",IconManagementDownload.repository("https://github.com/owner/repo.git"),"repository URL canonicalized");equal("owner/repo",IconManagementDownload.repository("owner/repo"),"explicit repository accepted");for(String url:new String[]{"http://github.com/o/r.zip","https://github.com.evil.invalid/a.zip","https://user@github.com/a.zip","https://github.com:444/a.zip","https://github.com/a.zip#x"})rejected(()->IconManagementDownload.checkedUrl(url),"download origin gate");String release=json(map("assets",Arrays.asList(map("name","icon-pack-v3.zip","size",1024,"browser_download_url","https://github.com/o/r/releases/download/v3/icon-pack-v3.zip"))));equal("github.com",IconManagementDownload.releaseAsset(release).getHost(),"explicit v3 Release asset selected");rejected(()->IconManagementDownload.releaseAsset(release.replace("icon-pack-v3.zip","icon-pack.zip")),"legacy Release is not fallback");}
    private static Path namedArchive(Path directory,String id,String name)throws Exception{Map<String,Object> metadata=manifest(map("wifi.1",asset("assets/a.png","mask"),"wifi.2",asset("assets/b.png","color")));metadata.put("id",id);metadata.put("name",name);return zip(directory,mapBytes("manifest.json",bytes(json(metadata)),"assets/a.png",png(true),"assets/b.png",png(true)));}
    private static Map<String,byte[]> mapBytes(Object... pairs){Map<String,byte[]> out=new LinkedHashMap<>();for(int i=0;i<pairs.length;i+=2)out.put((String)pairs[i],(byte[])pairs[i+1]);return out;}
    private static IconManagementRepository.Pack install(FilesContext context,Path archive)throws Exception{try(IconManagementRepository.PreparedPack pending=IconManagementRepository.prepare(context,archive.toFile(),"")){return pending.commit(()->true);}}
    private static void clean(Path directory)throws Exception{try(java.util.stream.Stream<Path> paths=Files.walk(directory)){for(Path path:paths.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(path);}}
    private static IconManagementRepository.Pack namedConflict(Task task)throws Exception{checks++;try{task.run();throw new AssertionError("Name collision accepted");}catch(IconManagementRepository.NameConflictException expected){return expected.existing;}}
    private static IconManagementRepository.Pack already(Task task)throws Exception{checks++;try{task.run();throw new AssertionError("Same content silently reused");}catch(IconManagementRepository.AlreadyInstalledException expected){return expected.existing;}}
    private static void namesAndRaces()throws Exception{
        Path directory=Files.createTempDirectory("c17-icon-names-");FilesContext context=new FilesContext(directory);
        try{
            equal("foo",IconManagementRepository.nameKey("　ＦＯＯ　"),"NFKC spaces/fullwidth comparison");equal(IconManagementRepository.nameKey("café"),IconManagementRepository.nameKey("cafe\u0301"),"canonical Unicode name comparison");equal("i",IconManagementRepository.nameKey("I"),"case comparison uses ROOT locale");
            equal(IconManagementRepository.nameKey("C17示例库 · PNG"),IconManagementRepository.nameKey("C17 Rounded27 · PNG"),"old visible example spelling shares name key");rejected(()->IconManagementRepository.nameKey("　"),"normalized blank name rejected");
            Path firstArchive=namedArchive(directory,"first-library","ＦＯＯ"),secondArchive=namedArchive(directory,"second-library","foo");IconManagementRepository.Pack first=install(context,firstArchive);byte[] firstManifest=first.manifest.bytes();int events=context.resolver.changes.size();
            try(IconManagementRepository.PreparedPack second=IconManagementRepository.prepare(context,secondArchive.toFile(),"")){
                String id=second.pack.id;equal(null,second.status().existing,"different body is not already installed");equal(first.id,second.status().nameConflict.id,"preview identifies exact conflicting library");equal(first.id,namedConflict(()->second.commit(" FOO ",()->true)).id,"commit rejects normalized display collision");equal(events,context.resolver.changes.size(),"blocked collision sends no publication event");
                previewPixels(second.preview("wifi.1",32),32,"name-collision draft remains usable");equal(first.id,namedConflict(()->second.rename("Ｆｏｏ")).id,"explicit draft rename repeats collision gate");equal("Bar",second.rename(" Bar ").name,"explicit draft rename updates only staged label");equal(1,IconManagementRepository.list(context).size(),"draft rename does not import");equal(null,second.status().nameConflict,"unique changed draft becomes importable");equal(id,second.commit("Bar",()->true).id,"name change cannot alter content identity");
            }
            equal(2,IconManagementRepository.list(context).size(),"distinct renamed content is installed once");equal("ＦＯＯ",IconManagementRepository.get(context,first.id).name,"new import never overwrites previous label");
            try(IconManagementRepository.PreparedPack duplicate=IconManagementRepository.prepare(context,firstArchive.toFile(),"Different draft")){
                equal(first.id,duplicate.status("Anything").existing.id,"same-content preview explicitly identifies existing library");equal(first.id,already(()->duplicate.commit("Different draft",()->true)).id,"same content cannot silently discard import name");equal(first.id,already(()->duplicate.rename("New unique name")).id,"same content cannot be made a second library by draft rename");equal("ＦＯＯ",duplicate.useExisting(()->true).name,"explicit existing-library action uses displayed existing name");
            }
            IconManagementRepository.Pack bar=IconManagementRepository.list(context).stream().filter(p->p.name.equals("Bar")).findFirst().orElseThrow();equal(bar.id,namedConflict(()->IconManagementRepository.rename(context,first.id,"ＢＡＲ")).id,"installed rename has same uniqueness rule");equal("ＦＯＯ",IconManagementRepository.get(context,first.id).name,"failed rename preserves stored old label");equal(first.id,IconManagementRepository.rename(context,first.id,"Baz").id,"installed rename preserves references and identity");equal(true,Arrays.equals(firstManifest,IconManagementRepository.get(context,first.id).manifest.bytes()),"rename does not modify immutable manifest");
            Path legacyArchive=namedArchive(directory,"legacy-example","C17 Rounded 27");IconManagementRepository.Pack legacy=install(context,legacyArchive);equal("C17示例库",legacy.name,"legacy package visible name is canonical");try(IconManagementRepository.PreparedPack fresh=IconManagementRepository.prepare(context,namedArchive(directory,"new-example","C17示例库").toFile(),"")){equal(legacy.id,fresh.status().nameConflict.id,"legacy and current visible example names conflict");}
            // Existing old duplicates remain readable; only new/active rename operations are constrained.
            Path barLabel=directory.resolve(IconManagementRepository.FOLDER).resolve(bar.id).resolve("name.json");Files.writeString(barLabel,json(map("name","Baz")));equal(2L,IconManagementRepository.list(context).stream().filter(p->p.name.equals("Baz")).count(),"old duplicated names are neither renamed nor deleted");namedConflict(()->IconManagementRepository.rename(context,first.id,"Baz"));IconManagementRepository.rename(context,bar.id,"Bar restored");
            ExecutorService workers=Executors.newFixedThreadPool(2);
            try{
                try(IconManagementRepository.PreparedPack left=IconManagementRepository.prepare(context,namedArchive(directory,"race-left","Race").toFile(),"");IconManagementRepository.PreparedPack right=IconManagementRepository.prepare(context,namedArchive(directory,"race-right","Race").toFile(),"")){
                    equal(null,left.status().nameConflict,"first pending initially has free name");equal(null,right.status().nameConflict,"second pending may initially have same free name");CountDownLatch go=new CountDownLatch(1);
                    Callable<Object> a=()->{go.await();try{return left.commit("Race",()->true);}catch(IconManagementRepository.NameConflictException conflict){return conflict;}};Callable<Object> b=()->{go.await();try{return right.commit("Race",()->true);}catch(IconManagementRepository.NameConflictException conflict){return conflict;}};
                    Future<Object> fa=workers.submit(a),fb=workers.submit(b);go.countDown();Object ra=fa.get(5,TimeUnit.SECONDS),rb=fb.get(5,TimeUnit.SECONDS);equal(1,(ra instanceof IconManagementRepository.Pack?1:0)+(rb instanceof IconManagementRepository.Pack?1:0),"only one concurrent equal-name publication wins");equal(1,(ra instanceof IconManagementRepository.NameConflictException?1:0)+(rb instanceof IconManagementRepository.NameConflictException?1:0),"loser gets an actionable name conflict");
                    IconManagementRepository.PreparedPack loser=ra instanceof IconManagementRepository.Pack?right:left;equal("Race renamed",loser.rename("Race renamed").name,"loser can change retained draft after race");loser.commit(()->true);
                }
                Path same=namedArchive(directory,"same-content-race","Same body");try(IconManagementRepository.PreparedPack left=IconManagementRepository.prepare(context,same.toFile(),"Same A");IconManagementRepository.PreparedPack right=IconManagementRepository.prepare(context,same.toFile(),"Same B")){
                    CountDownLatch go=new CountDownLatch(1);Future<Object> a=workers.submit(()->{go.await();try{return left.commit(()->true);}catch(IconManagementRepository.AlreadyInstalledException existing){return existing;}});Future<Object> b=workers.submit(()->{go.await();try{return right.commit(()->true);}catch(IconManagementRepository.AlreadyInstalledException existing){return existing;}});go.countDown();Object ra=a.get(5,TimeUnit.SECONDS),rb=b.get(5,TimeUnit.SECONDS);
                    equal(1,(ra instanceof IconManagementRepository.Pack?1:0)+(rb instanceof IconManagementRepository.Pack?1:0),"same-content concurrent pending publishes only one copy");equal(1,(ra instanceof IconManagementRepository.AlreadyInstalledException?1:0)+(rb instanceof IconManagementRepository.AlreadyInstalledException?1:0),"same-content loser explicitly sees installed result");IconManagementRepository.PreparedPack loser=ra instanceof IconManagementRepository.Pack?right:left;IconManagementRepository.Pack winner=(IconManagementRepository.Pack)(ra instanceof IconManagementRepository.Pack?ra:rb);equal(winner.name,loser.useExisting(()->true).name,"explicit concurrent reuse retains winning library name");
                }
            }finally{workers.shutdownNow();}
        }finally{IconManagementRepository.clear(context);clean(directory);}
    }
    private static void deletions()throws Exception{
        Path directory=Files.createTempDirectory("c17-icon-deletions-");FilesContext context=new FilesContext(directory);ActivationGuardPreferencesCheck.MemoryPreferences raw=new ActivationGuardPreferencesCheck.MemoryPreferences();
        try{
            IconManagementRepository.Pack pack=install(context,namedArchive(directory,"delete-me","Delete me"));String records=IconManagementSettings.applyPack(IconManagementSettings.DEFAULT,pack.id,Arrays.asList("wifi","hint"),false);records=IconManagementSettings.applyAppearance(records,"scope:wifi",new IconManagementSettings.Appearance("custom",0xff123456,0xffabcdef,37f));final String original=records,fallback=IconManagementSettings.removePack(records,pack.id);raw.values.put(IconManagementSettings.KEY,original);raw.values.put("unrelated","keep");
            final java.util.function.BooleanSupplier save=()->raw.edit().putString(IconManagementSettings.KEY,fallback).commit();final Runnable restore=()->{if(!raw.edit().putString(IconManagementSettings.KEY,original).commit())throw new IllegalStateException("restore refused");};int events=context.resolver.changes.size();
            try(IconManagementRepository.PreparedDeletion cancelled=IconManagementRepository.prepareDeletion(context,pack.id)){}equal(original,raw.values.get(IconManagementSettings.KEY),"cancel deletion preserves original choices");equal(pack.id,IconManagementRepository.get(context,pack.id).id,"cancel deletion preserves actual source");equal(events,context.resolver.changes.size(),"cancel deletion sends no event");
            try(IconManagementRepository.PreparedDeletion failed=IconManagementRepository.prepareDeletion(context,pack.id)){rejected(()->failed.commit(()->true,()->{save.getAsBoolean();return false;},restore),"failed settings persistence rolls deletion back");}equal(original,raw.values.get(IconManagementSettings.KEY),"failed settings commit restores even an in-memory changed value");equal(pack.id,IconManagementRepository.get(context,pack.id).id,"failed settings commit leaves resource identity intact");
            Path packagePath=directory.resolve(IconManagementRepository.FOLDER).resolve(pack.id);Map<String,byte[]> before=new LinkedHashMap<>();try(java.util.stream.Stream<Path> files=Files.walk(packagePath)){for(Path file:files.filter(Files::isRegularFile).toList())before.put(packagePath.relativize(file).toString(),Files.readAllBytes(file));}
            // The first asset is truly unlinked before the second removal fails; complete backups must restore it.
            android.system.Os.removeFailurePath=packagePath.resolve("assets/b.png").toFile().getAbsolutePath();try(IconManagementRepository.PreparedDeletion failed=IconManagementRepository.prepareDeletion(context,pack.id)){rejected(()->failed.commit(()->true,save,restore),"mid-directory native unlink failure restores deleted files");}finally{android.system.Os.removeFailurePath=null;}
            equal(original,raw.values.get(IconManagementSettings.KEY),"partial physical deletion restores exact choices");for(Map.Entry<String,byte[]> file:before.entrySet())equal(true,Arrays.equals(file.getValue(),Files.readAllBytes(packagePath.resolve(file.getKey()))),"partial deletion restores exact bytes "+file.getKey());equal(pack.id,IconManagementRepository.get(context,pack.id).id,"restored source passes whole-library digest");equal(events,context.resolver.changes.size(),"all failed deletions send no resource event");
            AtomicInteger lateChecks=new AtomicInteger();try(IconManagementRepository.PreparedDeletion late=IconManagementRepository.prepareDeletion(context,pack.id)){rejected(()->late.commit(()->lateChecks.incrementAndGet()<3,save,restore),"final revocation after all physical removals restores entire directory");}equal(original,raw.values.get(IconManagementSettings.KEY),"late cancellation restores settings");equal(pack.id,IconManagementRepository.get(context,pack.id).id,"late cancellation restores full original resources");
            try(IconManagementRepository.PreparedDeletion stale=IconManagementRepository.prepareDeletion(context,pack.id)){IconManagementRepository.rename(context,pack.id,"Latest name");int writes=raw.writes;rejected(()->stale.commit(()->true,save,restore),"stale deletion snapshot cannot erase later rename");equal(writes,raw.writes,"stale snapshot does not attempt preference changes");}equal("Latest name",IconManagementRepository.get(context,pack.id).name,"stale cancellation preserves latest label");events=context.resolver.changes.size();
            try(IconManagementRepository.PreparedDeletion success=IconManagementRepository.prepareDeletion(context,pack.id)){success.commit(()->true,save,restore);}equal(false,Files.exists(packagePath),"success removes the actual library directory");equal(fallback,raw.values.get(IconManagementSettings.KEY),"success saves only corresponding fallback choices");equal(0,IconManagementSettings.dependencies(fallback,pack.id),"deleted library leaves no source references");equal(37f,IconManagementSettings.parse(fallback).appearances.get("scope:wifi").opacity,"independent alpha survives source deletion");equal("keep",raw.values.get("unrelated"),"unrelated setting untouched");equal(events+1,context.resolver.changes.size(),"only successful deletion publishes one event");
            // If rollback itself fails, retain real backups and surface that failure instead of claiming success.
            IconManagementRepository.Pack blocked=install(context,namedArchive(directory,"rollback-blocked","Rollback blocked"));Path blockedPath=directory.resolve(IconManagementRepository.FOLDER).resolve(blocked.id);AtomicInteger gates=new AtomicInteger();
            try(IconManagementRepository.PreparedDeletion transaction=IconManagementRepository.prepareDeletion(context,blocked.id)){
                checks++;try{transaction.commit(()->{if(gates.incrementAndGet()<3)return true;try{Files.writeString(blockedPath,"block directory restoration");}catch(IOException failure){throw new UncheckedIOException(failure);}return false;},()->true,()->{});throw new AssertionError("rollback obstruction swallowed");}
                catch(IOException incomplete){equal(true,incomplete.getMessage().contains("未完整恢复"),"rollback failure clearly surfaced");equal(true,incomplete.getSuppressed().length>0,"rollback cause retained");}
            }
            equal(true,Arrays.stream(Objects.requireNonNull(directory.resolve(IconManagementRepository.FOLDER).toFile().listFiles())).anyMatch(file->file.isDirectory()&&file.getName().startsWith("delete-")&&new File(file,"manifest.json").isFile()),"failed rollback keeps complete recoverable source backup");
        }finally{android.system.Os.removeFailurePath=null;IconManagementRepository.clear(context);clean(directory);}
    }
